19	package com.vrem.wifianalyzer.vendor.model;
20	
21	import android.support.annotation.NonNull;
22	
23	import org.apache.commons.lang3.StringUtils;
24	
25	class VendorUtils {
26	    static final int MAX_SIZE = 6;
27	    private static final String SEPARATOR = ":";
28	
29	    private VendorUtils() {
30	        throw new IllegalStateException("Utility class");
31	    }
32	
33	    @NonNull
34	    static String clean(String macAddress) {
35	        if (macAddress == null) {
36	            return StringUtils.EMPTY;
37	        }
38	        String result = macAddress.replace(SEPARATOR, "");
39	        return result.substring(0, Math.min(result.length(), MAX_SIZE)).toUpperCase();
40	    }
41	
42	    @NonNull
43	    static String toMacAddress(String source) {
44	        if (source == null) {
45	            return StringUtils.EMPTY;
46	        }
47	        if (source.length() < MAX_SIZE) {
48	            return "*" + source + "*";
49	        }
50	        return source.substring(0, 2)
51	            + SEPARATOR + source.substring(2, 4)
52	            + SEPARATOR + source.substring(4, 6);
53	    }
54	
55	}
