19	package com.vrem.util;
20	
21	import android.support.annotation.NonNull;
22	
23	import org.apache.commons.collections4.Closure;
24	import org.apache.commons.collections4.CollectionUtils;
25	import org.apache.commons.collections4.IterableUtils;
26	import org.apache.commons.collections4.Predicate;
27	import org.apache.commons.lang3.StringUtils;
28	
29	import java.util.ArrayList;
30	import java.util.Arrays;
31	import java.util.HashSet;
32	import java.util.List;
33	import java.util.Locale;
34	import java.util.Set;
35	import java.util.SortedMap;
36	import java.util.TreeMap;
37	import java.util.TreeSet;
38	
39	public class LocaleUtils {
40	    static final Locale SPANISH = new Locale("es");
41	    static final Locale POLISH = new Locale("pl");
42	    static final Locale PORTUGUESE = new Locale("pt");
43	    static final Locale RUSSIAN = new Locale("ru");
44	    private static final String SEPARATOR = "_";
45	
46	    private LocaleUtils() {
47	        throw new IllegalStateException("Utility class");
48	    }
49	
50	    @NonNull
51	    public static Locale findByCountryCode(@NonNull String countryCode) {
52	        return find(SyncAvoid.AVAILABLE_LOCALES, new CountryCodePredicate(countryCode));
53	    }
54	
55	    @NonNull
56	    public static List<Locale> getAllCountries() {
57	        return new ArrayList<>(SyncAvoid.COUNTRIES_LOCALES.values());
58	    }
59	
60	    @NonNull
61	    public static Locale findByLanguageTag(@NonNull String languageTag) {
62	        return find(SyncAvoid.SUPPORTED_LOCALES, new LanguageTagPredicate(fromLanguageTag(languageTag)));
63	    }
64	
65	    @NonNull
66	    public static List<Locale> getSupportedLanguages() {
67	        return SyncAvoid.SUPPORTED_LOCALES;
68	    }
69	
70	    @NonNull
71	    public static String getDefaultCountryCode() {
72	        return SyncAvoid.DEFAULT.getCountry();
73	    }
74	
75	    @NonNull
76	    public static String getDefaultLanguageTag() {
77	        return LocaleUtils.toLanguageTag(SyncAvoid.DEFAULT);
78	    }
79	
80	    @NonNull
81	    private static Locale find(List<Locale> locales, Predicate<Locale> predicate) {
82	        Locale result = IterableUtils.find(locales, predicate);
83	        return result == null ? SyncAvoid.DEFAULT : result;
84	    }
85	
86	    @NonNull
87	    public static String toLanguageTag(@NonNull Locale locale) {
88	        return locale.getLanguage() + SEPARATOR + locale.getCountry();
89	    }
90	
91	    @NonNull
92	    private static Locale fromLanguageTag(@NonNull String languageTag) {
93	        String[] codes = languageTag.split(SEPARATOR);
94	        if (codes.length == 1) {
95	            return new Locale(codes[0]);
96	        }
97	        if (codes.length == 2) {
98	            return new Locale(codes[0], StringUtils.capitalize(codes[1]));
99	        }
100	        return SyncAvoid.DEFAULT;
101	    }
102	
103	    private static class CountryCodePredicate implements Predicate<Locale> {
104	        private final String countryCode;
105	
106	        private CountryCodePredicate(@NonNull String countryCode) {
107	            this.countryCode = StringUtils.capitalize(countryCode);
108	        }
109	
110	        @Override
111	        public boolean evaluate(Locale locale) {
112	            return countryCode.equals(locale.getCountry());
113	        }
114	    }
115	
116	    private static class CountriesPredicate implements Predicate<Locale> {
117	        private final Set<String> countryCodes;
118	
119	        private CountriesPredicate(@NonNull Set<String> countryCodes) {
120	            this.countryCodes = countryCodes;
121	        }
122	
123	        @Override
124	        public boolean evaluate(Locale locale) {
125	            return countryCodes.contains(locale.getCountry());
126	        }
127	    }
128	
129	    private static class LanguageTagPredicate implements Predicate<Locale> {
130	        private final Locale locale;
131	
132	        private LanguageTagPredicate(@NonNull Locale locale) {
133	            this.locale = locale;
134	        }
135	
136	        @Override
137	        public boolean evaluate(Locale object) {
138	            return object.getLanguage().equals(locale.getLanguage()) && object.getCountry().equals(locale.getCountry());
139	        }
140	    }
141	
142	    private static class SyncAvoid {
143	        private static final Locale DEFAULT = Locale.getDefault();
144	        private static final SortedMap<String, Locale> COUNTRIES_LOCALES;
145	        private static final List<Locale> AVAILABLE_LOCALES;
146	        private static final List<Locale> SUPPORTED_LOCALES;
147	
148	        static {
149	            Set<String> countryCodes = new TreeSet<>(Arrays.asList(Locale.getISOCountries()));
150	            List<Locale> availableLocales = Arrays.asList(Locale.getAvailableLocales());
151	            AVAILABLE_LOCALES = new ArrayList<>(CollectionUtils.select(availableLocales, new CountriesPredicate(countryCodes)));
152	            COUNTRIES_LOCALES = new TreeMap<>();
153	            IterableUtils.forEach(AVAILABLE_LOCALES, new CountryClosure());
154	            SUPPORTED_LOCALES = new ArrayList<>(new HashSet<>(Arrays.asList(
155	                Locale.GERMAN,
156	                Locale.ENGLISH,
157	                SPANISH,
158	                Locale.FRENCH,
159	                Locale.ITALIAN,
160	                POLISH,
161	                PORTUGUESE,
162	                RUSSIAN,
163	                Locale.SIMPLIFIED_CHINESE,
164	                Locale.TRADITIONAL_CHINESE, DEFAULT)));
165	        }
166	
167	        private static class CountryClosure implements Closure<Locale> {
168	            @Override
169	            public void execute(Locale locale) {
170	                String countryCode = locale.getCountry();
171	                COUNTRIES_LOCALES.put(StringUtils.capitalize(countryCode), locale);
172	            }
173	        }
174	    }
175	
176	}
