32	import static org.junit.Assert.assertEquals;
33	import static org.junit.Assert.assertTrue;
34	
35	@RunWith(RobolectricTestRunner.class)
36	public class VendorDBTest {
37	    private static final String VENDOR_NAME = "CISCO SYSTEMS INC";
38	    private static final String MAC_ADDRESS = "00:23:AB:8C:DF:10";
39	    private static final String VENDOR_NAME_INVALID = "XXXXX";
40	    private static final String MAC_ADDRESS_INVALID = "XX:XX:XX";
41	    private static final int VENDOR_SIZE = 17185;
42	    private static final int MACS_SIZE = 25579;
43	
44	    private VendorDB fixture;
45	
46	    @Before
47	    public void setUp() {
48	        MainActivity mainActivity = RobolectricUtil.INSTANCE.getActivity();
49	        fixture = new VendorDB(mainActivity.getResources());
50	    }
51	
52	    @Test
53	    public void testFindVendorName() {
54	        // execute
55	        String actual = fixture.findVendorName(MAC_ADDRESS);
56	        // validate
57	        assertEquals(VENDOR_NAME, actual);
58	    }
59	
60	    @Test
61	    public void testFindVendorNameWithNull() {
62	        // execute
63	        String actual = fixture.findVendorName(null);
64	        // validate
65	        assertEquals(StringUtils.EMPTY, actual);
66	    }
67	
68	    @Test
69	    public void testFindVendorNameWithInvalidMac() {
70	        // execute
71	        String actual = fixture.findVendorName(MAC_ADDRESS_INVALID);
72	        // validate
73	        assertEquals(StringUtils.EMPTY, actual);
74	    }
75	
76	    @Test
77	    public void testFindMacAddresses() {
78	        // setup
79	        int expectedSize = 842;
80	        // execute
81	        List<String> actual = fixture.findMacAddresses(VENDOR_NAME);
82	        // validate
83	        assertEquals(expectedSize, actual.size());
84	
85	        assertEquals("00:00:0C", actual.get(0));
86	        assertEquals("FC:FB:FB", actual.get(expectedSize - 1));
87	        assertEquals("00:9A:D2", actual.get(expectedSize / 2));
88	    }
89	
90	    @Test
91	    public void testFindMacAddressesWithNull() {
92	        // execute
93	        List<String> actual = fixture.findMacAddresses(null);
94	        // validate
95	        assertTrue(actual.isEmpty());
96	    }
97	
98	    @Test
99	    public void testFindMacAddressesWithInvalidName() {
100	        // execute
101	        List<String> actual = fixture.findMacAddresses(VENDOR_NAME_INVALID);
102	        // validate
103	        assertTrue(actual.isEmpty());
104	    }
105	
106	    @Test
107	    public void testFindVendors() {
108	        // execute
