28	import org.apache.commons.collections4.IterableUtils;
29	import org.apache.commons.collections4.Predicate;
30	import org.apache.commons.collections4.PredicateUtils;
31	import org.apache.commons.lang3.StringUtils;
32	
33	import java.util.ArrayList;
34	import java.util.List;
35	import java.util.Map;
36	import java.util.TreeMap;
37	
38	class VendorDB implements VendorService {
39	    private final Resources resources;
40	    private final Map<String, List<String>> vendors;
41	    private final Map<String, String> macs;
42	    private boolean loaded;
43	
44	    VendorDB(@NonNull Resources resources) {
45	        this.resources = resources;
46	        this.vendors = new TreeMap<>();
47	        this.macs = new TreeMap<>();
48	        this.loaded = false;
49	    }
50	
51	    @NonNull
52	    @Override
53	    public String findVendorName(String address) {
54	        String result = getMacs().get(VendorUtils.clean(address));
55	        return result == null ? StringUtils.EMPTY : result;
56	    }
57	
58	    @NonNull
59	    @Override
60	    public List<String> findMacAddresses(String vendorName) {
61	        if (StringUtils.isBlank(vendorName)) {
62	            return new ArrayList<>();
63	        }
64	        List<String> results = getVendors().get(vendorName);
65	        return results == null ? new ArrayList<>() : results;
66	    }
67	
68	    @NonNull
69	    @Override
70	    public List<String> findVendors() {
71	        return new ArrayList<>(getVendors().keySet());
72	    }
73	
74	    @NonNull
75	    @Override
76	    public List<String> findVendors(@NonNull String filter) {
77	        Predicate<String> predicate =
78	            PredicateUtils.anyPredicate(new StringContains(filter), new MacContains(filter));
79	        return new ArrayList<>(CollectionUtils.select(getVendors().keySet(), predicate));
80	    }
81	
82	    @NonNull
83	    Map<String, List<String>> getVendors() {
84	        load(resources);
85	        return vendors;
86	    }
87	
88	    @NonNull
89	    Map<String, String> getMacs() {
90	        load(resources);
91	        return macs;
92	    }
93	
94	    private void load(@NonNull Resources resources) {
95	        if (!loaded) {
96	            loaded = true;
97	            String[] lines = FileUtils.readFile(resources, R.raw.data).split("\n");
98	            for (String data : lines) {
99	                if (data != null) {
100	                    String[] parts = data.split("\\|");
101	                    if (parts.length == 2) {
102	                        List<String> addresses = new ArrayList<>();
103	                        String name = parts[0];
104	                        vendors.put(name, addresses);
105	                        int length = parts[1].length();
106	                        for (int i = 0; i < length; i += VendorUtils.MAX_SIZE) {
107	                            String mac = parts[1].substring(i, i + VendorUtils.MAX_SIZE);
108	                            addresses.add(VendorUtils.toMacAddress(mac));
109	                            macs.put(mac, name);
110	                        }
111	                    }
112	                }
113	            }
114	        }
115	    }
116	
117	    private class StringContains implements Predicate<String> {
118	        private final String filter;
119	
120	        private StringContains(@NonNull String filter) {
121	            this.filter = filter;
122	        }
123	
124	        @Override
125	        public boolean evaluate(String object) {
126	            return object.contains(filter);
127	        }
128	    }
129	
130	    private class MacContains implements Predicate<String> {
131	        private final String filter;
132	
133	        private MacContains(@NonNull String filter) {
134	            this.filter = filter;
135	        }
136	
137	        @Override
138	        public boolean evaluate(String object) {
139	            return IterableUtils.matchesAny(findMacAddresses(object), new StringContains(filter));
140	        }
141	    }
142	
143	}
