39	            int count = inputStream.read(bytes);
40	            if (count != size) {
41	                return StringUtils.EMPTY;
42	            }
43	            return new String(bytes);
44	        } catch (Exception e) {
45	            // file is corrupted
46	            return StringUtils.EMPTY;
